function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 2000) return 'nums needs 1 to 2000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 0 || v > 1000)) return 'Each value is a whole number from 0 to 1000.';
  return null;
}

