function largestUniqueNumber(nums) {
  const count = new Map();
  for (const num of nums) {
    count.set(num, (count.get(num) ?? 0) + 1);
  }
  let best = -1;
  for (const [value, times] of count) {
    if (times === 1 && value > best) {
      best = value;
    }
  }
  return best;
}

