function largestUniqueNumber(nums) {
  // Try the values from largest to smallest and count each one directly.
  const sorted = [...nums].sort((a, b) => b - a);
  for (const candidate of sorted) {
    if (nums.filter(x => x === candidate).length === 1) return candidate;
  }
  return -1;
}

