function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = int(1, 10), top = [1, 3, 6, 1000][int(0, 3)];
    return [Array.from({ length: n }, () => int(0, top))];
  }
  const n = int(1500, 2000);
  const shape = int(0, 2);
  if (shape === 0) return [Array.from({ length: n }, () => int(0, 1000))];
  // Every value at least twice, except perhaps one planted single value.
  const nums = [];
  while (nums.length + 2 <= n) {
    const value = int(0, 1000);
    nums.push(value, value);
  }
  if (shape === 2) {
    const single = int(0, 1000);
    for (let i = nums.length - 1; i >= 0; i--) if (nums[i] === single) nums.splice(i, 1);
    nums.push(single);
  }
  for (let i = nums.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [nums[i], nums[j]] = [nums[j], nums[i]];
  }
  return [nums];
}
